import { ProfileAvatar } from '@/components/registry/profile-avatar';

export function AuthorCard({
  name,
  role,
  avatarUrl,
  website,
}: {
  name: string;
  role: string;
  avatarUrl: string;
  website?: string;
}) {
  const content = (
    <>
      <ProfileAvatar src={avatarUrl} name={name} />
      <span className="min-w-0">
        <span className="block truncate text-sm font-semibold">{name}</span>
        <span className="block truncate text-sm text-muted-foreground">{role}</span>
      </span>
    </>
  );

  return website ? (
    <a href={website} className="flex items-center gap-3 rounded-xl focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring">
      {content}
    </a>
  ) : (
    <div className="flex items-center gap-3">{content}</div>
  );
}

import type { ComponentProps } from 'react';

export function ProfileAvatar({
  name,
  status = 'Available for selected projects',
  ...props
}: ComponentProps<'img'> & { name: string; status?: string }) {
  return (
    <span className="relative inline-flex size-12 shrink-0" title={`${name} — ${status}`}>
      <img
        {...props}
        alt={props.alt ?? name}
        className="size-full rounded-full border-2 border-background object-cover shadow-sm ring-1 ring-border"
      />
      <span
        aria-label={status}
        className="absolute right-0 bottom-0 size-3.5 rounded-full border-2 border-background bg-emerald-500"
      />
    </span>
  );
}
